@Service
public class OrderService {
    private static final Logger log = LoggerFactory.getLogger(OrderService.class);
    private final OrderRepository orderRepo;
    private final PaymentClient paymentClient;

    public Order processOrder(Long orderId) {
        try {
            var order = orderRepo.findById(orderId)
                .orElseThrow(() -> new OrderNotFoundException(orderId)); // Specific exception

            var payment = paymentClient.charge(order.getAmount());
            order.setPaymentId(payment.getId());
            return orderRepo.save(order);

        } catch (PaymentException e) {
            log.error("Payment failed for order {}", orderId, e); // Log with exception object
            throw new OrderProcessingException("Failed to process order " + orderId, e); // Wrap with cause
        }
        // Never catch Exception here — let unexpected failures propagate
    }
}

@RestController
public class OrderController {
    private static final Logger log = LoggerFactory.getLogger(OrderController.class);
    private final OrderService orderService;

    @PostMapping("/orders")
    public ResponseEntity<Order> createOrder(@RequestBody OrderRequest request) {
        try {
            var order = orderService.createOrder(request);
            return ResponseEntity.ok(order);

        } catch (PaymentException e) {
            // CORRECT: exception object as second parameter, with context
            log.error("Payment failed for customer {}, amount {}", 
                request.getCustomerId(), request.getAmount(), e);
            return ResponseEntity.status(PAYMENT_REQUIRED).build();

        } catch (ValidationException e) {
            log.warn("Invalid order request: {}", e.getMessage()); // Warn level, no stack trace needed
            return ResponseEntity.badRequest().build();
        }
    }
}

// BAD: Using exception for control flow
public User findUser(String email) {
    try {
        return userRepo.findByEmail(email).get(); // NoSuchElementException if empty
    } catch (NoSuchElementException e) {
        return createGuestUser(); // Exception as "not found" check
    }
}

// GOOD: Using Optional for control flow
public User findOrCreateUser(String email) {
    return userRepo.findByEmail(email)
        .orElseGet(() -> createGuestUser()); // Clear intent, no exception cost
}

// GOOD: Using explicit if-check
public boolean isOrderValid(Order order) {
    if (order.getItems().isEmpty()) { // Simple boolean check
        return false;
    }
    return order.getTotalAmount() > 0;
}

// Repository layer: rethrow without logging
@Repository
public class OrderRepository {
    public Order findById(Long id) {
        try {
            return jdbcTemplate.queryForObject(sql, mapper, id);
        } catch (EmptyResultDataAccessException e) {
            throw new OrderNotFoundException(id, e); // Rethrow, no logging
        }
    }
}

// Service layer: rethrow without logging
@Service
public class OrderService {
    public Order getOrder(Long id) {
        var order = orderRepo.findById(id); // Propagates OrderNotFoundException
        return order;
    }
}

// Controller layer: log once at the boundary
@RestControllerAdvice
public class GlobalExceptionHandler {
    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(OrderNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleNotFound(OrderNotFoundException e) {
        log.error("Order not found: {}", e.getMessage(), e); // Log once here
        return ResponseEntity.notFound().build();
    }
}

// BAD: Catching NPE masks the bug
public String getUserName(Long userId) {
    try {
        User user = userService.getUser(userId);
        return user.getName().toUpperCase(); // NPE if user or name is null
    } catch (NullPointerException e) {
        return "Unknown"; // Hides the fact that getUser returned null
    }
}

// GOOD: Use Optional to handle absence explicitly
public String getUserName(Long userId) {
    return userService.findUser(userId) // Returns Optional<User>
        .map(User::getName)
        .map(String::toUpperCase)
        .orElse("Unknown"); // Clear intent: user might not exist
}

// GOOD: Fail-fast with validation
public Order createOrder(Customer customer, List<Item> items) {
    Objects.requireNonNull(customer, "customer cannot be null");
    Objects.requireNonNull(items, "items cannot be null");
    if (items.isEmpty()) {
        throw new IllegalArgumentException("items cannot be empty");
    }
    return new Order(customer, items);
}

@Service
public class OrderService {
    private final OrderRepository orderRepo;
    private final CustomerRepository customerRepo;

    public Order createOrder(Long customerId, List<OrderItem> items, BigDecimal discount) {
        // Fail-fast validation at entry point
        Objects.requireNonNull(customerId, "customerId cannot be null");
        Objects.requireNonNull(items, "items cannot be null");

        if (items.isEmpty()) {
            throw new IllegalArgumentException("Order must have at least one item");
        }
        if (discount != null && discount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("Discount cannot be negative");
        }

        // Now safe to proceed — all inputs validated
        var customer = customerRepo.findById(customerId)
            .orElseThrow(() -> new CustomerNotFoundException(customerId));

        var order = new Order(customer, items);
        if (discount != null) {
            order.applyDiscount(discount);
        }
        return orderRepo.save(order);
    }
}
